UPDATE risk_knowledge_checks SET pass_condition='ARL-KB-105 is eligible for a PASS only when sampled findings have accountable owner, due date, classification rationale, remediation evidence requirement and a reviewer-controlled closure workflow. Observations must be bound to the exact assessed version, executed within written test authority where applicable, and independently accepted by an accountable human; missing evidence remains INCONCLUSIVE.', fail_condition='ARL-KB-105 fails when reports describe risk but do not create accountable work, so critical issues remain open indefinitely. A FAIL requires evidence of that actual condition in the approved scope and an accountable human finding; absent or inadequate observations remain INCONCLUSIVE rather than proving absence or breach.', content_digest='6de3b653bf0615e9379b5ec7dda038e3d9c1bcaa96635fe3675920d8a2c8f100' WHERE entry_id='ARL-KB-105';
UPDATE risk_knowledge_entries SET review_json='{"human_review_required":true,"last_reviewed":"2026-10-05","next_review_due":"2026-12-04","change_triggers":["ARL-KB-106 remediation, target version, retest method or acceptance-criteria change","ARL-KB-106 new bypass, regression, concurrency or authorization path relevant to the finding","ARL-KB-106 failed retest, residual exploit or unsupported closure evidence","ARL-KB-106 evidence expiry or material scope, architecture or assessed-version change"],"review_status":"Evidence and decision-criterion wording revised; independent practitioner and customer validation required"}', content_digest='0b8bc34923ae76ee4800c03621692af6be5b18493a9c72f11140fa881f70dbf0' WHERE id='ARL-KB-106';
UPDATE risk_knowledge_checks SET pass_condition='ARL-KB-106 is eligible for a PASS only when the exact remediated release passes a repeat of the original confirmed failure and relevant regression or bypass cases before an accountable reviewer authorizes closure. Observations must be bound to the exact assessed version, executed within written test authority where applicable, and independently accepted by an accountable human; missing evidence remains INCONCLUSIVE.', fail_condition='ARL-KB-106 fails when a code change or declaration closes the finding even though the original attack still succeeds through another path. A FAIL requires evidence of that actual condition in the approved scope and an accountable human finding; absent or inadequate observations remain INCONCLUSIVE rather than proving absence or breach.', content_digest='4937918cc240554f0f7488f190e06c8616a5aeca981d9931912d6506c8569aef' WHERE entry_id='ARL-KB-106';
UPDATE risk_knowledge_entries SET review_json='{"human_review_required":true,"last_reviewed":"2026-10-05","next_review_due":"2026-12-04","change_triggers":["ARL-KB-107 deployment gate, readiness model, evidence-chain or decision-authority change","ARL-KB-107 new production version, environment or material control change","ARL-KB-107 broken evidence chain, unsupported readiness or missing risk-acceptance evidence","ARL-KB-107 evidence expiry or material scope, architecture or assessed-version change"],"review_status":"Evidence and decision-criterion wording revised; independent practitioner and customer validation required"}', content_digest='6a857f7db7d50b25985e896d2e878ff3630b8eb0eef83b2e32163c9a460188bc' WHERE id='ARL-KB-107';
UPDATE risk_knowledge_checks SET pass_condition='ARL-KB-107 is eligible for a PASS only when the release decision can be reconstructed from the exact deployed identity, applicable controls, primary evidence, executed tests, open exceptions and attributable approvals. Observations must be bound to the exact assessed version, executed within written test authority where applicable, and independently accepted by an accountable human; missing evidence remains INCONCLUSIVE.', fail_condition='ARL-KB-107 fails when the organisation cannot show how declared controls, observations, attacks, runtime evidence, approvals, remediation and retest support release. A FAIL requires evidence of that actual condition in the approved scope and an accountable human finding; absent or inadequate observations remain INCONCLUSIVE rather than proving absence or breach.', content_digest='4a1598c1480ebc762e9303c867068f674bcacab04008cd13682bb687ddc50982' WHERE entry_id='ARL-KB-107';
UPDATE risk_knowledge_entries SET review_json='{"human_review_required":true,"last_reviewed":"2026-10-05","next_review_due":"2026-12-04","change_triggers":["ARL-KB-108 model, provider, data, tool, policy, threat or business-use change","ARL-KB-108 evidence expiry, exception expiry or reassessment-trigger change","ARL-KB-108 material drift, incident or stale-assurance evidence","ARL-KB-108 material scope, architecture or assessed-version change"],"review_status":"Evidence and decision-criterion wording revised; independent practitioner and customer validation required"}', content_digest='a629b1343b7717f699dd3d1894aaac4975439ecc153ef3a5c5d14daf4421545e' WHERE id='ARL-KB-108';
UPDATE risk_knowledge_checks SET pass_condition='ARL-KB-108 is eligible for a PASS only when evidence age, drift, incidents, provider/model/tool changes and due dates trigger documented reassessment or explicit accountable renewal before stale assurance is reused. Observations must be bound to the exact assessed version, executed within written test authority where applicable, and independently accepted by an accountable human; missing evidence remains INCONCLUSIVE.', fail_condition='ARL-KB-108 fails when controls, evidence and risk acceptance remain marked valid after models, data, tools, threats or business use change. A FAIL requires evidence of that actual condition in the approved scope and an accountable human finding; absent or inadequate observations remain INCONCLUSIVE rather than proving absence or breach.', content_digest='f5c058087b6d948ccf7d3667fefcf501aa665e45b4c946de0c39b85caa656b74' WHERE entry_id='ARL-KB-108';
